contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }
    function testRegression_property() public {
        c.Initialized();

        address newLog = address(0x123);
        bool ok;
        try c.SetLogFile(newLog) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
